package com.jnapanam.sportszone.training.service;
import com.jnapanam.sportszone.catalog.model.Facility;import com.jnapanam.sportszone.catalog.repository.*;import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.identity.model.*;import com.jnapanam.sportszone.identity.repository.UserRepository;import com.jnapanam.sportszone.training.dto.*;import com.jnapanam.sportszone.training.model.*;import com.jnapanam.sportszone.training.repository.*;import java.time.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TrainingService{
 private final TrainingProgramRepository programs;private final TrainingBatchRepository batches;private final TrainingEnrollmentRepository enrollments;private final TrainingAttendanceRepository attendance;private final SportRepository sports;private final FacilityRepository facilities;private final UserRepository users;private final long paymentMinutes;
 public TrainingService(TrainingProgramRepository p,TrainingBatchRepository b,TrainingEnrollmentRepository e,TrainingAttendanceRepository a,SportRepository s,FacilityRepository f,UserRepository u,@Value("${app.payment.pending-minutes:15}")long paymentMinutes){programs=p;batches=b;enrollments=e;attendance=a;sports=s;facilities=f;users=u;this.paymentMinutes=paymentMinutes;}
 @Transactional(readOnly=true)public List<ProgramResponse>publicPrograms(){return programs.findByStatusOrderByNameAsc(TrainingStatus.ACTIVE).stream().filter(p->p.getSport().isAvailableOn(LocalDate.now())).map(ProgramResponse::from).toList();}
 @Transactional(readOnly=true)public List<BatchResponse>publicBatches(){return batches.findByStatusOrderByStartDateAscStartTimeAsc(TrainingStatus.ACTIVE).stream().filter(b->!b.getEndDate().isBefore(LocalDate.now()) && b.getProgram().getSport().isAvailableOn(LocalDate.now()) && b.getFacility().isAvailableOn(LocalDate.now())).map(this::response).toList();}
 @Transactional(readOnly=true)public List<ProgramResponse>allPrograms(){return programs.findAllByOrderByNameAsc().stream().map(ProgramResponse::from).toList();}@Transactional(readOnly=true)public List<BatchResponse>allBatches(){return batches.findAllByOrderByStartDateAscStartTimeAsc().stream().map(this::response).toList();}
 @Transactional public ProgramResponse createProgram(ProgramRequest r){validateAge(r.minAge(),r.maxAge());if(programs.existsByCodeIgnoreCase(r.code()))throw new ConflictException("Training program code already exists");var sport=sports.findByCodeIgnoreCase(r.sportCode()).orElseThrow(()->new NotFoundException("Sport not found"));return ProgramResponse.from(programs.save(new TrainingProgram(r.code(),sport,r.name(),r.description(),r.minAge(),r.maxAge(),r.level())));}
 @Transactional public ProgramResponse updateProgram(UUID id,ProgramRequest r){validateAge(r.minAge(),r.maxAge());TrainingProgram p=program(id);if(!p.getCode().equalsIgnoreCase(r.code()))throw new BadRequestException("Training program code cannot be changed");p.update(sports.findByCodeIgnoreCase(r.sportCode()).orElseThrow(()->new NotFoundException("Sport not found")),r.name(),r.description(),r.minAge(),r.maxAge(),r.level());return ProgramResponse.from(p);}
 @Transactional public ProgramResponse programStatus(UUID id,TrainingStatusRequest r){TrainingProgram p=program(id);p.status(r.status());return ProgramResponse.from(p);}
 @Transactional public BatchResponse createBatch(BatchRequest r){validateBatch(r);TrainingProgram p=programs.findByCodeIgnoreCase(r.programCode()).orElseThrow(()->new NotFoundException("Training program not found"));Facility f=facilities.findByCodeIgnoreCase(r.facilityCode()).orElseThrow(()->new NotFoundException("Facility not found"));if(!f.getSport().getId().equals(p.getSport().getId()))throw new BadRequestException("Facility sport must match training program sport");User c=coach(r.coachEmail());return response(batches.save(new TrainingBatch(p,f,c,r.name(),r.startDate(),r.endDate(),r.startTime(),r.endTime(),r.daysOfWeek(),r.capacity(),r.fee())));}
 @Transactional public BatchResponse updateBatch(UUID id,BatchRequest r){validateBatch(r);TrainingBatch b=batch(id);if(!b.getProgram().getCode().equalsIgnoreCase(r.programCode()))throw new BadRequestException("Training batch program cannot be changed");Facility f=facilities.findByCodeIgnoreCase(r.facilityCode()).orElseThrow(()->new NotFoundException("Facility not found"));if(!f.getSport().getId().equals(b.getProgram().getSport().getId()))throw new BadRequestException("Facility sport must match training program sport");long enrolled=enrollments.countByBatchIdAndStatusIn(id,List.of(EnrollmentStatus.ENROLLED,EnrollmentStatus.PENDING_PAYMENT));if(r.capacity()<enrolled)throw new ConflictException("Capacity cannot be lower than active enrollments");b.update(f,coach(r.coachEmail()),r.name(),r.startDate(),r.endDate(),r.startTime(),r.endTime(),r.daysOfWeek(),r.capacity(),r.fee());return response(b);}
 @Transactional public BatchResponse batchStatus(UUID id,TrainingStatusRequest r){TrainingBatch b=batch(id);b.status(r.status());return response(b);}
 @Transactional public EnrollmentResponse enroll(UUID userId,UUID batchId,EnrollmentRequest r){TrainingBatch b=batches.findLocked(batchId).orElseThrow(()->new NotFoundException("Training batch not found"));if(b.getStatus()!=TrainingStatus.ACTIVE||b.getEndDate().isBefore(LocalDate.now())||!b.getProgram().getSport().isAvailableOn(LocalDate.now())||!b.getFacility().isAvailableOn(LocalDate.now()))throw new ConflictException("Training batch is not open");Integer min=b.getProgram().getMinAge(),max=b.getProgram().getMaxAge();if((min!=null&&r.participantAge()<min)||(max!=null&&r.participantAge()>max))throw new BadRequestException("Participant age is outside the program age range");if(enrollments.existsByBatchIdAndUserIdAndStatusIn(batchId,userId,List.of(EnrollmentStatus.ENROLLED,EnrollmentStatus.PENDING_PAYMENT)))throw new ConflictException("Customer is already registered for this batch");if(enrollments.countByBatchIdAndStatusIn(batchId,List.of(EnrollmentStatus.ENROLLED,EnrollmentStatus.PENDING_PAYMENT))>=b.getCapacity())throw new ConflictException("Training batch is full");User u=users.findById(userId).orElseThrow(()->new UnauthorizedException("User not found"));boolean paymentRequired=b.getFee().signum()>0;return EnrollmentResponse.from(enrollments.save(new TrainingEnrollment(b,u,r.participantName(),r.participantAge(),paymentRequired,Instant.now().plusSeconds(paymentMinutes*60))));}
 @Transactional(readOnly=true)public List<EnrollmentResponse>mine(UUID userId){return enrollments.findByUserIdOrderByEnrolledAtDesc(userId).stream().map(EnrollmentResponse::from).toList();}
 @Transactional public EnrollmentResponse cancel(UUID userId,UUID id){TrainingEnrollment e=enrollment(id);if(!e.getUser().getId().equals(userId))throw new NotFoundException("Enrollment not found");if(e.getStatus()!=EnrollmentStatus.ENROLLED&&e.getStatus()!=EnrollmentStatus.PENDING_PAYMENT)throw new ConflictException("Enrollment cannot be cancelled");e.cancel();return EnrollmentResponse.from(e);}
 @Transactional(readOnly=true)public List<EnrollmentResponse>roster(UUID batchId){batch(batchId);return enrollments.findByBatchIdOrderByEnrolledAtAsc(batchId).stream().map(EnrollmentResponse::from).toList();}
 @Transactional public void attendance(UUID enrollmentId,AttendanceRequest r){TrainingEnrollment e=enrollment(enrollmentId);if(e.getStatus()!=EnrollmentStatus.ENROLLED)throw new ConflictException("Attendance cannot be marked for a cancelled enrollment");TrainingBatch b=e.getBatch();if(r.sessionDate().isBefore(b.getStartDate())||r.sessionDate().isAfter(b.getEndDate())||!b.getDaysOfWeek().contains(r.sessionDate().getDayOfWeek()))throw new BadRequestException("Date is not a scheduled training session");TrainingAttendance a=attendance.findByEnrollmentIdAndSessionDate(enrollmentId,r.sessionDate()).orElseGet(()->new TrainingAttendance(e,r.sessionDate(),r.present()));a.mark(r.present());attendance.save(a);}
 @Transactional public int cleanupUnpaid(){int count=0;for(TrainingEnrollment e:enrollments.findByStatusAndPaymentExpiresAtLessThanEqual(EnrollmentStatus.PENDING_PAYMENT,Instant.now())){e.expirePayment();count++;}return count;}
 private BatchResponse response(TrainingBatch b){return BatchResponse.from(b,enrollments.countByBatchIdAndStatusIn(b.getId(),List.of(EnrollmentStatus.ENROLLED,EnrollmentStatus.PENDING_PAYMENT)));}private TrainingProgram program(UUID id){return programs.findById(id).orElseThrow(()->new NotFoundException("Training program not found"));}private TrainingBatch batch(UUID id){return batches.findById(id).orElseThrow(()->new NotFoundException("Training batch not found"));}private TrainingEnrollment enrollment(UUID id){return enrollments.findById(id).orElseThrow(()->new NotFoundException("Enrollment not found"));}
 private User coach(String email){if(email==null||email.isBlank())return null;User u=users.findByEmailIgnoreCase(email).orElseThrow(()->new NotFoundException("Coach not found"));if(u.getRoles().stream().noneMatch(r->r.getName()==RoleName.COACH))throw new BadRequestException("Assigned user must have COACH role");return u;}private static void validateAge(Integer min,Integer max){if(min!=null&&max!=null&&max<min)throw new BadRequestException("maxAge must be at least minAge");}private static void validateBatch(BatchRequest r){if(r.endDate().isBefore(r.startDate()))throw new BadRequestException("endDate must be on or after startDate");if(!r.endTime().isAfter(r.startTime()))throw new BadRequestException("endTime must be after startTime");}
}
